    '\nObjC.import("Foundation");\nfunction run(paths) {\n  var metadata = Object.create(null);\n  function inspect(url) {\n    var key = ObjC.unwrap(url.path);\n    if (metadata[key]) return metadata[key];\n    var isDirectory = Ref();\n    var exists = $.NSFileManager.defaultManager.fileExistsAtPathIsDirectory(url.path, isDirectory);\n    var values = exists ? url.resourceValuesForKeysError($([$.NSURLIsUbiquitousItemKey]), null) : null;\n    return metadata[key] = {\n      icloud: !!values && ObjC.deepUnwrap(values).NSURLIsUbiquitousItemKey === true,\n      directory: !!exists && !!isDirectory[0],\n      unavailable: !!exists && !values\n    };\n  }\n  return JSON.stringify(paths.map(function(p) {\n    try {\n      var url = $.NSURL.fileURLWithPath(p);\n      var resolvedPath = ObjC.unwrap(url.URLByResolvingSymlinksInPath.path);\n      var unavailable = false;\n      // Missing paths can return an empty dictionary. Check up to the nearest\n      // existing directory, which also catches newly created files in iCloud.\n      for (var depth = 0; depth < 128; depth++) {\n        var urls = [url, url.URLByResolvingSymlinksInPath];\n        var directory = false;\n        for (var i = 0; i < urls.length; i++) {\n          var values = inspect(urls[i]);\n          if (values.icloud) {\n            return { path: p, resolved: resolvedPath, icloud: true };\n          }\n          if (values.unavailable) unavailable = true;\n          if (values.directory) directory = true;\n        }\n        if (directory) break;\n        var parent = url.URLByDeletingLastPathComponent;\n        if (ObjC.unwrap(parent.path) === ObjC.unwrap(url.path)) break;\n        url = parent;\n      }\n      return { path: p, resolved: resolvedPath, icloud: false, unavailable: unavailable };\n    } catch (_) {\n      return { path: p, resolved: p, icloud: false, unavailable: true };\n    }\n  }));\n}',
