      const wrap = document.createElement("div");
      wrap.className = "gesture-reject";
      wrap.style.left = bx + "px";
      wrap.style.top = by + "px";
      wrap.style.width = bw + "px";
      wrap.style.height = bh + "px";
      const shake = document.createElement("div");
      shake.className = "gesture-reject-shake";
      const c = document.createElement("canvas");
