    "</div>\n      <script>\n        let startX = 0, startY = 0, dragging = false;\n        const sel = document.getElementById('selection');\n        const dims = document.getElementById('dims');\n        const hint = document.getElementById('hint');\n        let hintVisible = true;\n\n        document.addEventListener('mousemove', (e) => {\n          if (hintVisible && !dragging) {\n            hint.style.left = (e.clientX + 16) + 'px';\n            hint.style.top = (e.clientY + 16) + 'px';\n            hint.style.opacity = '1';\n          }\n\n          if (!dragging) return;\n          const x = Math.min(e.clientX, startX);\n          const y = Math.min(e.clientY, startY);\n          const w = Math.abs(e.clientX - startX);\n          const h = Math.abs(e.clientY - startY);\n          sel.style.left = x + 'px';\n          sel.style.top = y + 'px';\n          sel.style.width = w + 'px';\n          sel.style.height = h + 'px';\n          dims.style.display = 'block';\n          dims.style.left = (x + w + 8) + 'px';\n          dims.style.top = (y + h + 8) + 'px';\n          dims.textContent = Math.round(w) + ' \\u00d7 ' + Math.round(h);\n        });\n\n        document.addEventListener('mousedown', (e) => {\n          startX = e.clientX;\n          startY = e.clientY;\n          dragging = true;\n          document.title = 'drag:start';\n          hintVisible = false;\n          hint.style.opacity = '0';\n          document.body.style.background = 'transparent';\n          sel.style.display = 'block';\n          sel.style.left = startX + 'px';\n          sel.style.top = startY + 'px';\n          sel.style.width = '0';\n          sel.style.height = '0';\n        });\n\n        document.addEventListener('mouseup', (e) => {\n          if (!dragging) return;\n          dragging = false;\n          const x = Math.min(e.clientX, startX);\n          const y = Math.min(e.clientY, startY);\n          const w = Math.abs(e.clientX - startX);\n          const h = Math.abs(e.clientY - startY);\n          sel.style.display = 'none';\n          dims.style.display = 'none';\n          document.body.style.background = 'transparent';\n          if (w > 10 && h > 10) {\n            document.title = 'region:' + [Math.round(x), Math.round(y), Math.round(w), Math.round(h)].join(',');\n          } else {\n            document.title = 'drag:end';\n          }\n        });\n      <\/script>\n    </body></html>",
