    'function paintPointingTrail(ctx, trail, t, lifeMs) {\n  const HUE = 214;\n  const TRAIL_LIFE = lifeMs;\n  const PAD = 14;\n  let prevBox = null;\n  // Normal (source-over) compositing + ONE continuous stroke per pass. This\n  // is what keeps the trail a clean, even color: additive blending plus\n  // per-segment round caps used to pile up at every point and read as\n  // bright dots. A single path stroked once paints each pixel exactly once.\n  ctx.globalCompositeOperation = "source-over";\n  ctx.lineCap = "round";\n  ctx.lineJoin = "round";\n\n  if (trail.length >= 2) {\n    const n = trail.length;\n    const tail = trail[0];\n    const head = trail[n - 1];\n    let minX = Infinity,\n      minY = Infinity,\n      maxX = -Infinity,\n      maxY = -Infinity;\n    // One VoiceOS-blue gradient down the whole trail: constant hue, only the\n    // alpha fades from the (older) tail to the (newer) head, so the color\n    // stays clean and even and just dissolves at the tail.\n    const grad = ctx.createLinearGradient(tail.x, tail.y, head.x, head.y);\n    for (let i = 0; i < n; i++) {\n      const p = trail[i];\n      if (p.x < minX) minX = p.x;\n      if (p.y < minY) minY = p.y;\n      if (p.x > maxX) maxX = p.x;\n      if (p.y > maxY) maxY = p.y;\n      const k = Math.max(0, 1 - (t - p.t) / TRAIL_LIFE);\n      grad.addColorStop(i / (n - 1), "hsla(" + HUE + ",100%,60%," + k + ")");\n    }\n    // Smooth the raw cursor points into a flowing curve: use each point as\n    // a quadratic control point and the midpoint between consecutive points\n    // as the on-curve anchor. Straight lineTo segments between sparse\n    // mousemove samples read as an angular, faceted ("pixelated") polyline;\n    // quadratics round it into a clean stroke.\n    const drawPath = () => {\n      ctx.beginPath();\n      ctx.moveTo(trail[0].x, trail[0].y);\n      for (let i = 1; i < n - 1; i++) {\n        const mx = (trail[i].x + trail[i + 1].x) / 2;\n        const my = (trail[i].y + trail[i + 1].y) / 2;\n        ctx.quadraticCurveTo(trail[i].x, trail[i].y, mx, my);\n      }\n      ctx.lineTo(trail[n - 1].x, trail[n - 1].y);\n    };\n    ctx.strokeStyle = grad;\n    // Soft outer glow (wide, faint) then the crisp core — both concentric on\n    // the same path, so they never bead.\n    ctx.globalAlpha = 0.14;\n    ctx.lineWidth = 20;\n    drawPath();\n    ctx.stroke();\n    ctx.globalAlpha = 0.55;\n    ctx.lineWidth = 8;\n    // stroke() preserves the current path; reuse its geometry for the core.\n    ctx.stroke();\n    prevBox = {\n      x: minX - PAD,\n      y: minY - PAD,\n      w: maxX - minX + 2 * PAD,\n      h: maxY - minY + 2 * PAD,\n    };\n  } else if (trail.length === 1) {\n    // The very first point of a hold, before a second arrives: a small\n    // clean dot as feedback.\n    const h = trail[0];\n    const k = Math.max(0, 1 - (t - h.t) / TRAIL_LIFE);\n    ctx.globalAlpha = 0.55;\n    ctx.fillStyle = "hsla(" + HUE + ",100%,60%," + k + ")";\n    ctx.beginPath();\n    ctx.arc(h.x, h.y, 7, 0, Math.PI * 2);\n    ctx.fill();\n    ctx.globalAlpha = 1;\n    prevBox = { x: h.x - PAD, y: h.y - PAD, w: 2 * PAD, h: 2 * PAD };\n  }\n\n  return prevBox;\n}',
