    "\n  CREATE TABLE dictations (\n    id TEXT PRIMARY KEY,\n    user_id TEXT,\n    final_transcription TEXT,\n    transcriber_response TEXT,\n    language_model_response TEXT,\n    audio_blob_id TEXT,\n    duration_seconds REAL,\n    sample_rate INTEGER,\n    word_count INTEGER,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    deleted_at TEXT,\n    sync_failed_at TEXT\n  );\n\n  CREATE TABLE dictionary (\n    id TEXT PRIMARY KEY,\n    user_id TEXT NOT NULL,\n    text TEXT NOT NULL,\n    description TEXT,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    deleted_at TEXT,\n    sync_failed_at TEXT,\n    auto_added INTEGER DEFAULT 0,\n    app_identifiers TEXT\n  );\n\n  CREATE TABLE voice_sessions (\n    id TEXT PRIMARY KEY,\n    user_id TEXT NOT NULL,\n    transcript TEXT,\n    generated_text TEXT,\n    app_name TEXT,\n    window_title TEXT,\n    audio_blob_id TEXT,\n    duration_seconds REAL,\n    sample_rate INTEGER,\n    word_count INTEGER,\n    mode INTEGER NOT NULL DEFAULT 0,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    deleted_at TEXT,\n    sync_failed_at TEXT,\n    app_icon_id TEXT\n  );\n\n  CREATE TABLE app_icons (\n    id TEXT PRIMARY KEY,\n    user_id TEXT NOT NULL,\n    app_name TEXT NOT NULL,\n    icon_base64 TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    UNIQUE(user_id, app_name)\n  );\n\n  CREATE TABLE edit_session_records (\n    id TEXT PRIMARY KEY,\n    user_id TEXT NOT NULL,\n    dictation_id TEXT NOT NULL,\n    app_name TEXT,\n    pasted_text TEXT NOT NULL,\n    final_text TEXT NOT NULL,\n    modifications TEXT NOT NULL,\n    status TEXT NOT NULL,\n    end_reason TEXT NOT NULL,\n    keyword_decision TEXT,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    sync_failed_at TEXT\n  );\n\n  CREATE INDEX IF NOT EXISTS idx_edit_session_records_user_created\n    ON edit_session_records(user_id, created_at DESC);\n\n  CREATE INDEX IF NOT EXISTS idx_edit_session_records_dictation\n    ON edit_session_records(dictation_id);\n\n  CREATE TABLE agent_sessions (\n    id TEXT PRIMARY KEY,\n    user_id TEXT NOT NULL,\n    voice_session_id TEXT,\n    title TEXT,\n    initial_app_name TEXT,\n    initial_window_title TEXT,\n    source TEXT,\n    status TEXT NOT NULL DEFAULT 'active',\n    preview_text TEXT,\n    last_response_text TEXT,\n    pending_confirmation_json TEXT,\n    result_snapshot_json TEXT,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    deleted_at TEXT,\n    sync_failed_at TEXT\n  );\n\n  CREATE TABLE agent_turns (\n    id TEXT PRIMARY KEY,\n    session_id TEXT NOT NULL,\n    sequence INTEGER NOT NULL,\n    -- VOS-1239: the analytics interaction this turn belongs to.\n    interaction_id TEXT,\n    user_message TEXT,\n    assistant_response TEXT,\n    assistant_response_html TEXT,\n    status TEXT NOT NULL DEFAULT 'completed',\n    started_at TEXT,\n    completed_at TEXT,\n    duration_ms INTEGER,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    FOREIGN KEY(session_id) REFERENCES agent_sessions(id) ON DELETE CASCADE,\n    UNIQUE(session_id, sequence)\n  );\n\n  CREATE TABLE agent_tool_calls (\n    id TEXT PRIMARY KEY,\n    turn_id TEXT NOT NULL,\n    sequence INTEGER NOT NULL,\n    tool_name TEXT NOT NULL,\n    tool_slug TEXT,\n    display_name TEXT,\n    status TEXT NOT NULL DEFAULT 'observed',\n    input_json TEXT,\n    output_summary TEXT,\n    created_at TEXT NOT NULL,\n    completed_at TEXT,\n    FOREIGN KEY(turn_id) REFERENCES agent_turns(id) ON DELETE CASCADE\n  );\n\n  CREATE INDEX IF NOT EXISTS idx_agent_sessions_user_updated\n    ON agent_sessions(user_id, updated_at DESC);\n  CREATE INDEX IF NOT EXISTS idx_agent_sessions_user_created\n    ON agent_sessions(user_id, created_at DESC);\n  CREATE INDEX IF NOT EXISTS idx_agent_sessions_voice_session\n    ON agent_sessions(voice_session_id);\n  CREATE INDEX IF NOT EXISTS idx_agent_turns_interaction\n    ON agent_turns(interaction_id);\n  CREATE INDEX IF NOT EXISTS idx_agent_turns_session_sequence\n    ON agent_turns(session_id, sequence);\n  CREATE INDEX IF NOT EXISTS idx_agent_tool_calls_turn_sequence\n    ON agent_tool_calls(turn_id, sequence);\n\n  CREATE TABLE chatgpt_sessions (\n    id TEXT PRIMARY KEY,\n    user_id TEXT NOT NULL,\n    title TEXT,\n    conversation_url TEXT,\n    image_path TEXT,\n    image_alt TEXT,\n    response_text TEXT,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL\n  );\n\n  CREATE INDEX IF NOT EXISTS idx_chatgpt_sessions_user_updated\n    ON chatgpt_sessions(user_id, updated_at DESC);\n\n  CREATE TABLE agent_day_summaries (\n    id TEXT PRIMARY KEY,\n    user_id TEXT NOT NULL,\n    day TEXT NOT NULL,\n    summary TEXT,\n    covered_through TEXT,\n    updated_at TEXT NOT NULL,\n    UNIQUE(user_id, day)\n  );\n\n  CREATE INDEX IF NOT EXISTS idx_agent_day_summaries_user_day\n    ON agent_day_summaries(user_id, day);\n\n  CREATE TABLE sync_metadata (\n    id TEXT PRIMARY KEY,\n    timestamp TEXT\n  );\n",
