    function moveTag(x, y) {
      if (tagDone) return;
      if (tagLast) tagTravel += Math.hypot(x - tagLast.x, y - tagLast.y);
      tagLast = { x, y };
      if (tagTravel > TAG_FADE_TRAVEL) {
        tagDone = true;
        tagEl.style.opacity = "0";
        return;
      }
      if (captureHold) return;
      placeTag(x, y);
      tagEl.style.opacity = "1";
    }

    // The cursor left this display — hide its tag until it returns (each
    // display's overlay has its own tag; without this the pill would freeze
    // in place when the user crosses onto another monitor).
    window.addEventListener("mouseout", (e) => {
      if (!e.relatedTarget && !tagDone) tagEl.style.opacity = "0";
    });

    // PHANTOM GUARD: ~1 frame after the overlay appears under the cursor,
    // Chromium synthesizes a trusted mouseover/mousemove burst with NO user
    // movement — with coordinates ~10px off the real cursor (measured, macOS
    // two-display setup). Untreated, that one event stamps an off-cursor dot,
    // opens a stroke (⇒ screenshot capture ⇒ a stray one-dot drawing attached
    // to the turn), and yanks the hint tag off its seeded spot. The event is
    // isTrusted with movementX/Y of 0, so no property identifies it. Instead:
    // the first event is only recorded as a dormant reference, and everything
    // stays inert until the cursor travels ARM_TRAVEL px from it. Repeat
    // phantoms land on the same point and stay dormant; the first real
    // movement continues from the true cursor (beyond ARM_TRAVEL from the
    // phantom point) and is processed normally, so no stroke latency is lost.
    const ARM_TRAVEL = 4;
    let armRef = null;
    let armed = false;

    // Continuous draw — NO click needed. The moment the cursor moves (for
    // real — see PHANTOM GUARD), a single stroke opens and keeps extending
    // for the whole hold, so the blue wand trail follows the cursor the
    // entire time. Mouse buttons do nothing; the stroke ends only when the
    // session finalizes (PTT release). handleMove is the guard-free core,
    // shared by the live listener and the __replayPath approach backfill.
    function handleMove(x, y, sampleTime) {
      moveTag(x, y);
      if (pointerDown) {
        // Movement with the button held is a DRAG (a window being moved, a
        // selection) — not drawing: no comet on the glass, no recorded ink,
        // no gesture material (Jonah 2026-08-26: dragging must stay CLEAR).
        // End the live stroke so pre-drag ink and whatever follows the
        // release stay separate strokes — one continuous stroke would
        // composite a straight chord across the drag's travel. The gesture
        // buffer clears for the same no-stitching rule feedGesture enforces.
        current = null;
        gPoints.length = 0;
        return;
      }
      if (!current) {
        // First movement of the hold: open the (single, continuous) stroke and
        // signal the main process to grab the clean screenshot for this display.
        //
        // The trail is NOT withheld and the system cursor is NOT hidden while
        // that capture is in flight — the old first-stroke captureHold left
        // the user with no cursor and no trail for the capture's ~100-400ms,
        // right as drawing began (Jonah 2026-08-25). The price is that the
        // young comet (and the crosshair ScreenCaptureKit bakes in) can land
        // in the clean frame: harmless for the wide drawing-reference, whose
        // composited ink retraces this exact recorded path, and gesture
        // crops never trust this frame (it is marked trail-tainted main-side
        // and refreshed under a proper hold — see handleGestureDetected).
        //
        // The hint chip still must not bake in next to the target: hide it
        // INSTANTLY (no fade) and for good — once the user is drawing, the
        // "point to show" affordance has done its job. The tag-in ENTRANCE
        // ANIMATION overrides inline opacity while it plays (animations beat
        // inline styles in the cascade), and the first stroke usually lands
        // inside its 200ms — so without killing it the "instantly hidden"
        // chip kept animating INTO the clean capture (field-reported: the
        // tag visible in the screenshot).
        tagDone = true;
        tagEl.style.transition = "none";
        tagEl.style.animation = "none";
        tagEl.style.opacity = "0";
        current = [{ x: x, y: y, t: pathNow(sampleTime) }];
        strokes.push(current);
        emit(x, y);
        feedGesture(x, y);
        // Signal the capture only after the hidden chip has actually been
        // PRESENTED (double rAF = composited to glass) — a same-task title
        // change let the capture race the compositor by a frame and
        // snapshot the un-hidden state.
        const seq = ++strokeSeq;
        requestAnimationFrame(function () {
          requestAnimationFrame(function () {
            document.title = "stroke:" + seq;
          });
        });
        return;
      }
      const last = current[current.length - 1];
      if (Math.abs(x - last.x) < 1 && Math.abs(y - last.y) < 1) return;
      current.push({ x: x, y: y, t: pathNow(sampleTime) });
      emit(x, y);
      feedGesture(x, y);
    }

    document.addEventListener("mousemove", (e) => {
      if (!armed) {
        if (!armRef) {
          armRef = { x: e.clientX, y: e.clientY };
          return;
        }
        if (Math.hypot(e.clientX - armRef.x, e.clientY - armRef.y) < ARM_TRAVEL) {
          return;
        }
        armed = true;
      }
      handleMove(e.clientX, e.clientY);
    });

    // Approach backfill, called by the main process with the cursor path it
    // recorded between the Agent hold's commit and this overlay going live
    // (pre-threshold travel + arm-poll lag + window raise — none of which
    // this renderer could see). The path is trusted, so it BYPASSES the
    // phantom guard and arms it — routed through the guard as synthetic
    // mousemoves, the guard's dormant-reference dance ate the first point
    // and the start of every trace went missing (Jonah 2026-08-25). Usually
    // this runs before the window is shown and simply opens the stroke at
    // the movement's true origin; if live events won the race and already
    // opened it, the approach is PREPENDED so the recorded geometry stays
    // origin→…→live with no zigzag (those points skip moveTag/feedGesture —
    // an approach glide is not circle material, and the chip is already
    // hidden).
    window.__replayPath = function (points) {
      if (!points || points.length === 0) return;
      armed = true;
      if (!current) {
        for (const p of points) handleMove(p.x, p.y, p.t);
        return;
      }
      const t = now();
      for (let i = points.length - 1; i >= 0; i--) {
        current.unshift({ x: points[i].x, y: points[i].y, t: Math.min(points[i].t ?? Infinity, current[0].t - 0.001) });
        trail.unshift({ x: points[i].x, y: points[i].y, t: t });
      }
      ensureRaf();
    };

    // Mid-session frame REFRESH — SHIELD-UNSAFE FALLBACK ONLY since
    // 2026-08-27: both platforms now shield the grab with
    // setContentProtection so the trail never pauses (see
    // refreshCleanCapture); this hold runs only on Windows pre-2004 builds
    // or when a shielded grab came back blacked (GDI capturer, e.g. RDP).
    // It hides tag + cursor and pauses NEW trail points, but the
    // existing comet stays on the glass, fading naturally. Its points are
    // the just-closed loop's tail, retraced at full strength by the
    // composited ink in the crop, so the residue is invisible — whereas the
    // old "clear the comet outright" here made the trail visibly vanish at
    // every capture (Jonah 2026-08-25: always show the trail). Resolves only
    // after the hidden tag/cursor state has PRESENTED (double rAF) so the
    // capture can't race the compositor.
    window.__beginCaptureHold = function () {
      return new Promise(function (resolve) {
        captureHold = true;
        tagEl.style.transition = "none";
        tagEl.style.animation = "none";
        tagEl.style.opacity = "0";
        document.body.style.cursor = "none";
        requestAnimationFrame(function () {
          requestAnimationFrame(resolve);
        });
      });
    };
    window.__endCaptureHold = function () {
      captureHold = false;
      tagEl.style.transition = "";
      document.body.style.cursor = "crosshair";
    };

    // Called by the main process when a pre-created warm spare is adopted for
    // a session: the spare's HTML baked the tag parked offscreen (it was
    // built before any hold existed), so bring it to the cursor now — the
    // same placement the cold path bakes in at build time.
    window.__seedTag = function (x, y) {
      placeTag(x, y);
      tagEl.style.opacity = "1";
    };

    // Called by the main process at finalize. Renders the PERSISTENT strokes in
    // VoiceOS blue onto a throwaway offscreen canvas (the visible canvas only
    // ever holds the transient wand trail) and returns it as a transparent PNG.
    window.__exportInk = function () {
      if (strokes.length === 0) return null;
      const off = document.createElement("canvas");
      off.width = Math.round(window.innerWidth * dpr);
      off.height = Math.round(window.innerHeight * dpr);
      const o = off.getContext("2d");
      o.setTransform(dpr, 0, 0, dpr, 0, 0);
      o.lineCap = "round";
      o.lineJoin = "round";
      // Two passes so one stroke's glow never covers another's core: all
      // glows first, then all cores. The live trail's look (wide faint
      // glow + core in the same blue) — but the core stays OPAQUE in this
      // layer: the blend fades the whole layer to DRAWING_INK_OPACITY
      // (the trail core's 0.55), so self-overlaps don't double-darken.
      // The glow's alpha here is RELATIVE to the core (0.14/0.55 ≈ 0.25),
      // landing it at the trail's 0.14 after the blend.
      for (const pass of [
        { style: "hsla(" + HUE + ",100%,60%,0.25)", width: 20, dot: 10 },
        { style: "hsl(" + HUE + ",100%,60%)", width: 8, dot: 7 },
      ]) {
        o.strokeStyle = pass.style;
        o.fillStyle = pass.style;
        o.lineWidth = pass.width;
        for (const points of strokes) {
          if (points.length === 1) {
            // A click without a drag is a point marker.
            o.beginPath();
            o.arc(points[0].x, points[0].y, pass.dot, 0, Math.PI * 2);
            o.fill();
          } else {
            o.beginPath();
            o.moveTo(points[0].x, points[0].y);
            for (let i = 1; i < points.length; i++) o.lineTo(points[i].x, points[i].y);
            o.stroke();
          }
        }
      }
      return off.toDataURL("image/png");
    };
